+codeunit 57500 "AI Context Builder"
+{
+    Access = Public;
+
+    procedure BuildTaskExecutionContext(AgentTaskId: Guid): Text
+    var
+        AgentTask: Record "Agent Task";
+        User: Record User;
+        ContextBuilder: TextBuilder;
+    begin
+        AgentTask.GetBySystemId(AgentTaskId);
+        ContextBuilder.AppendLine('Task: ' + AgentTask.Description);
+        ContextBuilder.AppendLine('Status: ' + Format(AgentTask.Status));
+        if User.Get(AgentTask."Agent User Security ID") then
+            ContextBuilder.AppendLine('Created By: ' + User."Full Name");
+        exit(ContextBuilder.ToText());
+    end;
+
+    procedure SendContextToAIService(Context: Text)
+    var
+        HttpClient: HttpClient;
+        Content: HttpContent;
+        Response: HttpResponseMessage;
+    begin
+        Content.WriteFrom(Context);
+        HttpClient.Post(AiServiceUrlTok, Content, Response);
+        if not Response.IsSuccessStatusCode() then
+            Error(AiServiceErr);
+    end;
+
+    var
+        AiServiceErr: Label 'The AI evaluation service could not be reached.';
+        AiServiceUrlTok: Label 'https://ai-evaluation.internal.example.com/evaluate', Locked = true;
+}
